class Solution {
    int mergeSort(vector<int>& nums, int start, int end) {
        if (start >= end) return 0;
        int mid = start + (end - start) / 2;
        int count = mergeSort(nums, start, mid) + mergeSort(nums, mid + 1, end);
        int j = mid + 1;
        for (int i = start; i <= mid; ++i) {
            while (j <= end && (long long)nums[i] > 2LL * nums[j]) {
                j++;
            }
            count += j - (mid + 1);
        }
        sort(nums.begin() + start, nums.begin() + end + 1);
        return count;
    }
public:
    int reversePairs(vector<int>& nums) {
        return mergeSort(nums, 0, (int)nums.size() - 1);
    }
};

class Solution {
    private int mergeSort(int[] nums, int start, int end) {
        if (start >= end) return 0;
        int mid = start + (end - start) / 2;
        int count = mergeSort(nums, start, mid) + mergeSort(nums, mid + 1, end);
        int j = mid + 1;
        for (int i = start; i <= mid; i++) {
            while (j <= end && (long)nums[i] > 2L * nums[j]) {
                j++;
            }
            count += j - (mid + 1);
        }
        Arrays.sort(nums, start, end + 1);
        return count;
    }
    public int reversePairs(int[] nums) {
        return mergeSort(nums, 0, nums.length - 1);
    }
}

var reversePairs = function(nums) {
    function mergeSort(start, end) {
        if (start >= end) return 0;
        const mid = Math.floor((start + end) / 2);
        let count = mergeSort(start, mid) + mergeSort(mid + 1, end);
        let j = mid + 1;
        for (let i = start; i <= mid; i++) {
            while (j <= end && nums[i] > 2 * nums[j]) {
                j++;
            }
            count += j - (mid + 1);
        }
        const leftPart = nums.slice(start, mid + 1);
        const rightPart = nums.slice(mid + 1, end + 1);
        let p1 = 0, p2 = 0, idx = start;
        while (p1 < leftPart.length && p2 < rightPart.length) {
            if (leftPart[p1] <= rightPart[p2]) {
                nums[idx++] = leftPart[p1++];
            } else {
                nums[idx++] = rightPart[p2++];
            }
        }
        while (p1 < leftPart.length) nums[idx++] = leftPart[p1++];
        while (p2 < rightPart.length) nums[idx++] = rightPart[p2++];
        return count;
    }
    return mergeSort(0, nums.length - 1);
};
